fn ordinal(n:usize)->Result<Cell<'static>, ValueError>{Ok(Cell::Integer(i64::try_from(n).map_err(|e| invalid(e.to_string()))?))}
fn checkpoint(c:&mut SqliteSnapshotControl<'_>,n:usize,total:usize)->Result<(), ValueError>{if n%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,n,total)?;}Ok(())}
type Entities<'a>=BTreeMap<i64,FloatRow<'a>>;
fn entities<'a>(d:&'a SqliteDatabase,table:&str,count:usize,floats:&'static[FloatColumn],c:&mut SqliteSnapshotControl<'_>)->Result<Entities<'a>, ValueError>{let rows=&d.table(table)?.rows;let mut out=Entities::new();for(n,row)in rows.iter().enumerate(){checkpoint(c,n,rows.len())?;let r=FloatRow::new(row,floats)?;if r.rowid<=0||r.integer(0)?!=r.rowid||r.values.len()!=count||out.insert(r.rowid,r).is_some(){return Err(invalid("EN1992 identity or owned column shape differs"));}}Ok(out)}
fn ordered<'a>(rows:impl IntoIterator<Item=FloatRow<'a>>,parent:i64,c:&mut SqliteSnapshotControl<'_>)->Result<Vec<FloatRow<'a>>, ValueError>{let mut out=BTreeMap::new();for(n,r)in rows.into_iter().enumerate(){checkpoint(c,n,0)?;let i=usize::try_from(r.integer(2)?).map_err(|e| invalid(e.to_string()))?;if r.integer(1)?!=parent||out.insert(i,r).is_some(){return Err(invalid("EN1992 parent or ordinal differs"));}}for(n,i)in out.keys().copied().enumerate(){checkpoint(c,n,out.len())?;if n!=i{return Err(invalid("EN1992 ordinals must be dense"));}}Ok(out.into_values().collect())}
fn groups<'a>(rows:Entities<'a>,parents:&Entities<'_>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<FloatRow<'a>>>, ValueError>{let mut out=BTreeMap::<i64,Vec<FloatRow<'a>>>::new();for(n,r)in rows.into_values().enumerate(){checkpoint(c,n,0)?;let p=r.integer(1)?;if !parents.contains_key(&p){return Err(invalid("EN1992 owning foreign key is dangling"));}out.entry(p).or_default().push(r);}Ok(out)}
fn optional_entities<'a>(rows:Entities<'a>,parents:&Entities<'_>,c:&mut SqliteSnapshotControl<'_>)->Result<Entities<'a>, ValueError>{for(n,id)in rows.keys().enumerate(){checkpoint(c,n,rows.len())?;if !parents.contains_key(id){return Err(invalid("EN1992 optional member entity is dangling"));}}Ok(rows)}
fn text(r:FloatRow<'_>,i:usize,c:&mut SqliteSnapshotControl<'_>)->Result<String, ValueError>{reconstruct_text(c,r.text(i)?)}
fn boolean(r:FloatRow<'_>,i:usize)->Result<bool, ValueError>{match r.integer(i)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("EN1992 boolean differs"))}}
fn u32_value(r:FloatRow<'_>,i:usize)->Result<u32, ValueError>{u32::try_from(r.integer(i)?).map_err(|e| invalid(e.to_string()))}
