fn read_member_kind(a:&str)->Result<MemberKind, ValueError>{match a{"Beam"=>Ok(MemberKind::Beam),"Slab"=>Ok(MemberKind::Slab),"Column"=>Ok(MemberKind::Column),"Wall"=>Ok(MemberKind::Wall),"FlatSlab"=>Ok(MemberKind::FlatSlab),"RibbedSlab"=>Ok(MemberKind::RibbedSlab),"TensionMember"=>Ok(MemberKind::TensionMember),"Bridge"=>Ok(MemberKind::Bridge),"LiquidRetaining"=>Ok(MemberKind::LiquidRetaining),_=>Err(invalid("EN1992 member kind differs"))}}
